# libagentxx 共享库导出符号白名单 (ELF version script)
#
# 目标: 将 libagentxx.so 导出面从"全部 C++ 符号 (约 17 万)"收敛为仅 FFI C API
# 与既有 C 入口, 供其他语言 FFI 干净调用 (dlopen/dlsym 只按名查找白名单符号):
#   - FFI C API (agentxx/ffi_api.h): agentxx_ffi_create/start/stop/... 等
#   - 既有 C 入口 (agentxx.h): agentxx_ffi_malloc/agentxx_ffi_free/agentxx_ffi_strdup_n
#   - 内置插件清单入口: agentxx_plugin_get_builtin_plugins (PluginManager 使用)
# local: * 隐藏其余全部符号 (libagentxx 内部 C++ 符号、静态链接的第三方库
#         符号: fmt/asio/sqlite/hyperscan/neograph 等), 避免污染 FFI 命名空间
#
# 构建侧注入 (agent/lib/CMakeLists.txt):
#   target_link_options(agentxx_shared PRIVATE "-Wl,--version-script=<本文件>")
# 仅作用于共享库; agentxx_static (cli/test/benchmark 消费) 不受影响。
#
# 注意: 新增导出符号时在此追加 (同时更新 agentxx/ffi_api.h 与文档)。
{
  global:
    agentxx_ffi_malloc;
    agentxx_ffi_free;
    agentxx_ffi_strdup_n;
    agentxx_ffi_api_version;
    agentxx_ffi_library_version;
    agentxx_ffi_strerror;
    agentxx_ffi_create;
    agentxx_ffi_start;
    agentxx_ffi_stop;
    agentxx_ffi_destroy;
    agentxx_ffi_send_input;
    agentxx_ffi_cancel;
    agentxx_ffi_select_model;
    agentxx_ffi_set_permission;
    agentxx_ffi_switch_session;
    agentxx_ffi_get_model_info;
    agentxx_ffi_get_context_messages;
    agentxx_ffi_list_sessions;
    agentxx_ffi_interrupt_respond;
    agentxx_ffi_drain_logs;
    agentxx_ffi_event_queue_create;
    agentxx_ffi_event_queue_free;
    agentxx_ffi_event_queue_on_event;
    agentxx_ffi_event_queue_pop;
    agentxx_plugin_get_builtin_plugins;
  local: *;
};